use vstd::prelude::*;

verus! {

    /// Linear search: return the index of the first occurrence of `target` in `nums`,
    /// or -1 if not found.
    ///
    /// Requirements:
    ///   - nums.len() <= i32::MAX as usize (so casting indices to i32 is safe).
    ///
    /// Ensures:
    ///   - If ret >= 0, then
    ///       let idx = ret as usize;
    ///       idx < nums.len(),
    ///       nums[idx] == target,
    ///       and for all j < idx, nums[j] != target.
    ///   - If ret < 0, then target does not appear in nums at any position.
    fn linear_search(nums: Vec<i32>, target: i32) -> (ret: i32)
        requires
            nums.len() <= i32::MAX as usize,
        ensures
            // case: found
            (ret >= 0 ==>
                let idx = ret as usize;
                idx < nums.len() &&
                nums[idx] == target &&
                forall j: usize :: j < idx ==> nums[j] != target
            ) &&
            // case: not found
            (ret < 0 ==>
                forall j: usize :: j < nums.len() ==> nums[j] != target
            )
    {
        let n: usize = nums.len();
        let mut i: usize = 0;
        // We maintain that for all j < i, nums[j] != target.
        while i < n
            invariant
                i <= n,
                forall j: usize :: j < i ==> nums[j] != target,
            decreases n - i,
        {
            if nums[i] == target {
                // we have found the first occurrence at index i
                let ret_idx: i32 = i as i32;
                // since i < n <= i32::MAX, this cast is safe
                return ret_idx;
            }
            i = i + 1;
        }
        // if we reach here, no element equals target
        -1
    }

}

